read.script:
const list = document.querySelector('ul.proposals-list');
if (!list) throw new Error('proposals list container missing');
const proposals = Array.from(list.querySelectorAll('.proposal'));
const active = proposals.filter(p => {
  const pill = p.querySelector('.status-pill');
  return pill && pill.textContent.trim().toLowerCase().includes('active review');
}).slice(0, 8);
return active.map(p => {
  const idEl = p.querySelector('.proposal-id');
  const titleEl = p.querySelector('.proposal-title');
  const pill = p.querySelector('.status-pill');
  const authorsEl = p.querySelector('.authors .proposal-detail-value, .author .proposal-detail-value, [class*="author"] .proposal-detail-value');
  return {
    id: idEl ? idEl.textContent.trim() : '',
    title: titleEl ? titleEl.textContent.trim() : '',
    status: pill ? pill.textContent.trim() : '',
    authors: authorsEl ? authorsEl.textContent.trim() : '',
    url: titleEl ? titleEl.href : ''
  };
});

return {
  seNumber: input.item.id,
  id: input.item.id,
  title: input.item.title,
  status: input.item.status,
  authors: input.item.authors,
  proposalUrl: input.item.url,
  url: input.item.url,
  classification: input.classification
};

return {
  inspectedScope: 'Inspected currently displayed Active Review proposals on https://www.swift.org/swift-evolution/ (first 8 in page order)',
  inspectedActiveReviewCount: input.activeProposals.length,
  selectedCount: input.classifiedProposals.length,
  selectedProposals: input.classifiedProposals
};
